<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';require_once dirname(__DIR__).'/app/Auth/SessionUser.php';require_once dirname(__DIR__).'/app/UI/Workspace.php';require_once dirname(__DIR__).'/app/UI/Conversation.php';require_once dirname(__DIR__).'/app/Search/GlobalSearch.php';
use TNL\Search\GlobalSearch;
header('Cache-Control: no-store');header("Content-Security-Policy: default-src 'self'; style-src 'self'; frame-src 'self'; img-src 'self' data: https:; form-action 'self'; base-uri 'none'; frame-ancestors 'self'");$db=tnl_db();$who=\TNL\Auth\SessionUser::require($db);$query=trim((string)($_GET['q']??''));$owner=(string)($_GET['owner']??'');$remote=($_GET['remote']??'1')==='1';$error='';$results=null;$server=null;$selected=null;$owners=GlobalSearch::owners($db,$who);
try{if(isset($_GET['sent'])){$selected=GlobalSearch::sharedSent($db,$who,(int)$_GET['sent']);if(!$selected){http_response_code(404);throw new InvalidArgumentException('Mensaje no disponible para tu cuenta.');}}elseif($query!==''){$results=GlobalSearch::local($db,$who,$query);if($remote){session_write_close();$server=GlobalSearch::remote($db,$who,$query,tnl_path('storage'),$owner);tnl_session();}}}catch(InvalidArgumentException $e){if(session_status()!==PHP_SESSION_ACTIVE)tnl_session();$error=$e->getMessage();}catch(Throwable $e){if(session_status()!==PHP_SESSION_ACTIVE)tnl_session();$error='No se pudo completar la búsqueda. Intenta nuevamente.';}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Buscar · TNL Mail</title><link rel="stylesheet" href="assets/app.css?v=0.13.0"><script src="assets/workspace.js?v=0.13.0" defer></script></head><body><div class="layout"><?php \TNL\UI\Workspace::sidebar($who['role'],'search',$who['name']);?><main class="main"><header class="page-header"><div><span class="eyebrow">CORREO Y CONTACTOS</span><h1>Búsqueda global</h1><p>Busca por nombre, empresa, dirección, destinatarios o texto de los mensajes.</p></div></header><?php if($error):?><p class="error" role="alert"><?=tnl_escape($error)?></p><?php endif;?>
<?php if($selected):?><?php \TNL\UI\Conversation::render([$selected],true);?><?php else:?><form method="get" class="panel search-options"><label>Buscar<input name="q" required minlength="2" maxlength="160" value="<?=tnl_escape($query)?>" placeholder="Ej.: Juan Galdamez, ideal@xempresa.com o cotización"></label><label>Buzones externos<select name="owner"><option value="">Todas mis cuentas conectadas</option><?php foreach($owners as $key=>$meta):?><option value="<?=tnl_escape($key)?>" <?=$owner===$key?'selected':''?>><?=tnl_escape($meta['email'])?></option><?php endforeach;?></select></label><input type="hidden" name="remote" value="0"><label class="inline-check"><input type="checkbox" name="remote" value="1" <?=$remote?'checked':''?>> Incluir texto de la bandeja de entrada en los servidores externos</label><button>Buscar información</button></form>
<?php if($results):?><p class="content-note">Los nombres de contactos se relacionan con sus correos solo cuando tienes permiso de lectura. Se muestran hasta 40 coincidencias por sección local y hasta 10 mensajes por buzón externo. Refina el texto para buscar resultados más concretos.</p><section class="panel"><h2>Contactos · <?=count($results['contacts'])?></h2><?php if(!$results['contacts']):?><p class="muted">No hay contactos coincidentes.</p><?php endif;?><?php foreach($results['contacts'] as $c):?><article class="search-result"><h3><a href="contacts.php?id=<?=(int)$c['id']?>"><?=tnl_escape($c['first_name'].' '.$c['last_name'])?></a></h3><p><?=tnl_escape($c['company'].' · '.$c['job_title'])?></p><?php if($c['can_read']):?><small><?=tnl_escape($c['email'])?><?=$c['phone']?' · '.tnl_escape($c['phone']):''?></small><?php else:?><small>Correo y teléfono privados. <a href="contacts.php?id=<?=(int)$c['id']?>">Solicitar permiso</a></small><?php endif;?></article><?php endforeach;?></section>
<?php foreach(['internal'=>'Chat del equipo','reception'=>'Recepción asignada','sent'=>'Mensajes enviados'] as $kind=>$title):?><section class="panel"><h2><?=tnl_escape($title)?> · <?=count($results[$kind])?></h2><?php if(!$results[$kind]):?><p class="muted">Sin coincidencias.</p><?php endif;?><?php foreach($results[$kind] as $item):?><article class="search-result"><h3><a href="<?=tnl_escape(tnl_url($item['href']))?>"><?=tnl_escape($item['title'])?></a></h3><small><?=tnl_escape($item['sender'])?></small><p><?=tnl_escape($item['snippet'])?></p></article><?php endforeach;?></section><?php endforeach;?>
<?php if($server):?><section class="panel"><h2>Correo recibido en servidores externos · <?=count($server['rows'])?></h2><p class="content-note"><?=$server['searched']?> de <?=$server['accounts']?> buzones consultados. Esta búsqueda no marca mensajes como leídos.</p><?php if($server['partial']):?><p class="notice">Se alcanzó el tiempo de búsqueda. Elige un buzón para consultar las cuentas restantes.</p><?php endif;?><?php foreach($server['errors'] as $failure):?><p class="error"><?=tnl_escape($failure)?></p><?php endforeach;?><?php foreach($server['rows'] as $item):?><article class="search-result"><h3><a href="<?=tnl_escape(tnl_url($item['href']))?>"><?=tnl_escape($item['title'])?></a></h3><small><?=tnl_escape($item['sender'])?></small><p><?=tnl_escape($item['snippet'])?></p></article><?php endforeach;?><?php if(!$server['rows']&&!$server['errors']):?><p class="muted">Sin coincidencias en la bandeja de entrada de las cuentas consultadas.</p><?php endif;?></section><?php endif;?><?php endif;?><?php endif;?></main></div></body></html>
